//! Declares the app's commands to Tauri, so each window may call only the
//! ones its capability grants (`capabilities/`): the main window all of
//! them, the radial overlay just what it shows. The list is read from
//! `generate_handler![...]` in `src/main.rs`, so there is one list.
//! Tauri writes `allow-<command>` permissions into
//! `permissions/autogenerated/`; this adds the set `main-window` (every
//! command) beside them. Both are build output, not kept in git.

use std::path::Path;

fn main() {
    println!("cargo:rerun-if-changed=src/main.rs");
    let main = std::fs::read_to_string("src/main.rs").expect("reading src/main.rs");
    let commands: &'static [&'static str] = Box::leak(handler_commands(&main).into_boxed_slice());
    assert!(
        !commands.is_empty(),
        "no commands found in generate_handler![...]"
    );
    let dir = Path::new("permissions/autogenerated");
    std::fs::create_dir_all(dir).expect("making permissions/autogenerated");
    let allowed: Vec<String> = commands
        .iter()
        .map(|c| format!("  \"allow-{}\",", c.replace('_', "-")))
        .collect();
    let set = format!(
        "# Automatically generated by build.rs - DO NOT EDIT!\n\n[[set]]\nidentifier = \"main-window\"\n\
         description = \"Every romforge command, for the main window.\"\npermissions = [\n{}\n]\n",
        allowed.join("\n")
    );
    let path = dir.join("main-window.toml");
    if std::fs::read_to_string(&path).ok().as_deref() != Some(set.as_str()) {
        std::fs::write(&path, set).expect("writing the main-window permission set");
    }
    let manifest = tauri_build::AppManifest::new().commands(commands);
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(manifest)).expect("tauri build");
}

/// The command names in `generate_handler![module::name, ...]`.
fn handler_commands(main: &str) -> Vec<&'static str> {
    let Some(start) = main.find("generate_handler![") else {
        return Vec::new();
    };
    let rest = &main[start + "generate_handler![".len()..];
    let list = &rest[..rest.find(']').unwrap_or(0)];
    list.split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| &*Box::leak(s.rsplit("::").next().unwrap_or(s).to_owned().into_boxed_str()))
        .collect()
}
